def add(title,typ='columns',lead='',items=None,takeaway='',pages='',notes='',**kw):
    s=dict(title=title,type=typ,lead=lead,source='教材第五章 '+pages if pages else '校园选址教学模拟 / 8 学时',notes=notes or '先请学生解释图表或计算的含义，再展开公式；要求说明数据、偏好和约束的来源。')
    if items is not None:s['items']=items
    if takeaway:s['takeaway']=takeaway
    s.update(kw);slides.append(s)
def table(title,headers,rows,**kw):add(title,'table',headers=headers,rows=rows,**kw)
def chart(title,series,items,xlabel,ylabel,**kw):add(title,'chart',series=series,items=items,xlabel=xlabel,ylabel=ylabel,**kw)
def eq(title,items,**kw):add(title,'equations',items=items,**kw)
